INSERT INTO `Service` (`id`, `title`, `slug`, `shortDescription`, `description`, `icon`, `technologies`, `seoTitle`, `seoDescription`, `displayOrder`, `status`, `createdAt`, `updatedAt`) VALUES
(UUID(), 'Web Application Development', 'web-application-development', 'High-performance, responsive React & Next.js applications custom-engineered for business growth.', 'We architect and build enterprise-grade web applications that deliver lightning-fast performance, flawless mobile responsiveness, and intuitive UI/UX. Using modern frameworks like Next.js, Node.js, and modern cloud databases, we ensure your platform scales effortlessly as your user base expands.', 'Globe', '["React","Next.js","Node.js","TypeScript","Tailwind CSS","MySQL","GraphQL"]', 'Custom Web Application Development Services | TechInPedia India', 'Build scalable, secure web applications with TechInPedia India. Node.js, Next.js, React, and MySQL expert developers.', 1, 'PUBLISHED', NOW(3), NOW(3))
INSERT INTO `Service` (`id`, `title`, `slug`, `shortDescription`, `description`, `icon`, `technologies`, `seoTitle`, `seoDescription`, `displayOrder`, `status`, `createdAt`, `updatedAt`) VALUES
(UUID(), 'Mobile App Development', 'mobile-app-development', 'Cross-platform iOS and Android applications crafted for native performance and user engagement.', 'Turn your mobile product vision into reality. We design and launch seamless iOS and Android applications built with React Native and Flutter. From API integrations to real-time sync and push notifications, our mobile apps deliver top-tier user experiences.', 'Smartphone', '["React Native","Flutter","iOS","Android","REST API","Firebase"]', 'Mobile App Development Agency | TechInPedia India', 'High-performance React Native & Flutter cross-platform mobile apps built for scale.', 2, 'PUBLISHED', NOW(3), NOW(3))
INSERT INTO `Service` (`id`, `title`, `slug`, `shortDescription`, `description`, `icon`, `technologies`, `seoTitle`, `seoDescription`, `displayOrder`, `status`, `createdAt`, `updatedAt`) VALUES
(UUID(), 'Custom Software & SaaS Development', 'custom-software-saas-development', 'End-to-end SaaS engineering, multi-tenant architectures, subscription billing, and cloud deployment.', 'Transform ideas into profitable SaaS products. We engineer multi-tenant cloud platforms, complete with user role management, billing gateway integrations (Stripe/Razorpay), automated analytics, and bulletproof security.', 'Cpu', '["Node.js","TypeScript","Prisma","MySQL","Docker","AWS","Stripe"]', 'SaaS & Custom Software Development | TechInPedia India', 'End-to-end SaaS architecture, cloud infrastructure, and custom software development.', 3, 'PUBLISHED', NOW(3), NOW(3))
